from __future__ import annotations

from student_content_le7_a import E, L, MAT, arith, cnt, n_words  # noqa: F401

OA7 = "LE07 OA 07"

FAROL = ("Cuando el pueblo instaló luces nuevas, Anselmo siguió encendiendo el viejo farol de la esquina. Los vecinos lo miraban y se encogían de hombros. "
         "Una noche de neblina espesa, las luces nuevas se apagaron por una falla, y el único brillo que guio a los niños de vuelta a casa fue el del farol de Anselmo.")

L(OA7, 1,
  MAT,
  "Aprenderé a formular preguntas interpretativas sobre un texto literario: preguntas que no se responden copiando una frase, sino razonando con evidencias.",
  ["Distingo situación, tema y juicio.", "Sé citar evidencia del texto."],
  ["Hay preguntas que se responden copiando una frase: «¿Qué hizo Anselmo con el farol?». Se llaman preguntas literales. Hay otras que exigen pensar: «¿Qué sugiere el texto sobre el valor de lo antiguo?». Se llaman preguntas interpretativas. No tienen una sola respuesta fija, pero tampoco cualquier respuesta sirve: las razonables se apoyan en lo que el texto dice y muestra.",
   "Una buena pregunta interpretativa tiene tres rasgos. Primero, nace de algo del texto: un gesto, un objeto, una decisión o una contradicción. Segundo, admite más de una respuesta razonable. Tercero, se puede responder con evidencia del texto. «¿Qué es la vida?» es demasiado amplia y no se ancla en el texto. «¿Por qué Anselmo sigue encendiendo el farol aunque nadie se lo pida?» sí se ancla.",
   "Para formularla se parte de una observación: «Los vecinos se encogen de hombros». Luego se pregunta por qué, para qué o qué significa. Las palabras «por qué», «qué sugiere», «qué muestra» y «qué sentido tiene» ayudan a escribir buenas preguntas interpretativas. Después, se elige una evidencia y se piensa qué respuesta posible la respaldaría."],
  [("pregunta literal", "pregunta que se responde con una frase explícita del texto"), ("pregunta interpretativa", "pregunta que exige razonar con evidencias del texto y admite más de una respuesta razonable"), ("anclar", "apoyar una pregunta o idea en algo concreto del texto"), ("evidencia", "dato del texto que respalda una respuesta")],
  [("Literal o interpretativa", f"Texto: «{FAROL}» ¿«¿Qué hizo Anselmo con el viejo farol?» es literal o interpretativa?",
    ["Veo si se responde copiando una frase.", "El texto dice que siguió encendiéndolo.", "Es una pregunta literal."],
    "Literal"),
   ("Crear una pregunta interpretativa", f"Texto: «{FAROL}» Observación: «Los vecinos se encogían de hombros». ¿Qué pregunta interpretativa nace de ella?",
    ["Parto de la observación.", "Pregunto por qué o qué sugiere.", "Por ejemplo: «¿Por qué los vecinos no valoran el farol hasta la noche de neblina?»"],
    "«¿Por qué los vecinos no valoran el farol hasta la noche de neblina?»")],
  [("Hacer preguntas cuya respuesta es una frase del texto y llamarlas interpretativas.", "Se confunde buscar un dato con interpretar.", "Pregunta por qué, para qué o qué sugiere."),
   ("Hacer preguntas tan amplias que el texto no las responde.", "Se olvida anclar.", "Parte de un detalle concreto del texto.")],
  ([E(f"Texto: «{FAROL}» ¿Quién siguió encendiendo el farol?", "Anselmo", "Es una pregunta literal con respuesta directa."),
    E("Una pregunta interpretativa, ¿se responde copiando una frase o razonando con evidencia?", "Razonando con evidencia", "No tiene una respuesta única explícita."),
    E(f"Texto: «{FAROL}» ¿Qué pasó con las luces nuevas la noche de neblina?", "Se apagaron por una falla", "Lo dice el texto.")],
   [E(f"Texto: «{FAROL}» Clasifica con L (literal) o I (interpretativa): 1) ¿Quién siguió encendiendo el farol? 2) ¿Por qué el texto muestra que lo viejo todavía puede ser útil? 3) ¿Qué hacían los vecinos al ver a Anselmo? Escribe las tres letras.", "L, I, L", "1 y 3 se responden con frases; 2 exige razonar."),
    E(f"Texto: «{FAROL}» ¿Qué pregunta interpretativa se puede responder con el texto: «¿Qué valor tiene mantener lo antiguo cuando hay algo nuevo?» o «¿Cuántos faroles hay en el mundo?»", "«¿Qué valor tiene mantener lo antiguo cuando hay algo nuevo?»", "Se ancla en el farol y las luces nuevas."),
    E("¿Cuántas respuestas razonables puede admitir una pregunta interpretativa: más de una o solo una?", "Más de una", "No hay una única respuesta, pero todas deben apoyarse en el texto.")],
   [E(f"Texto: «{FAROL}» ¿Cuál convierte la pregunta literal «¿Qué hizo Anselmo?» en interpretativa: «¿Qué significa que Anselmo siguiera encendiendo el farol aunque nadie se lo pidiera?» o «¿Cuándo encendió Anselmo el farol?»", "«¿Qué significa que Anselmo siguiera encendiendo el farol aunque nadie se lo pidiera?»", "Pide razonar sobre el sentido de su acción."),
    E(f"Texto: «{FAROL}» Para responder «¿Por qué es importante el farol?», ¿qué evidencia sirve más: «el único brillo que guio a los niños» o «los vecinos se encogían de hombros»?", "«el único brillo que guio a los niños»", "Muestra la utilidad del farol."),
    E(f"Texto: «{FAROL}» «¿Hizo bien Anselmo?» ¿Es literal o interpretativa?", "Interpretativa", "Exige valorar con razones apoyadas en el texto.")],
   [E("¿Por qué «¿Qué es la vida?» no es una buena pregunta interpretativa para este texto?", "Es demasiado amplia y no se ancla en el texto", "El texto no la responde."),
    E("Una pregunta cuya respuesta es solo «sí» o «no», sin razones posibles, ¿es interpretativa?", "No", "No admite razonamiento con evidencia.")],
   [E(f"Texto: «{FAROL}» ¿Cuántas de estas preguntas son interpretativas? 1) ¿Quién enciende el farol? 2) ¿Qué enseña el texto sobre la gratitud? 3) ¿Qué le ocurre a las luces? 4) ¿Por qué podría Anselmo seguir con el farol?", "2", "Las preguntas 2 y 4 exigen interpretar."),
    E(f"Texto: «{FAROL}» ¿Qué frase muestra la tensión entre lo nuevo y lo antiguo: «Cuando el pueblo instaló luces nuevas, Anselmo siguió encendiendo el viejo farol» o «los vecinos se encogían de hombros»?", "«Cuando el pueblo instaló luces nuevas, Anselmo siguió encendiendo el viejo farol»", "Contrapone las luces nuevas y el farol viejo.")]),
  [E("Tu curso lee un cuento en que una niña guarda una piedra sin decir por qué. ¿Qué pregunta interpretativa nace del detalle: «¿Por qué guarda la piedra y qué sugiere esa acción?» o «¿Cuántos años tiene la niña?»", "«¿Por qué guarda la piedra y qué sugiere esa acción?»", "Parte de un detalle y exige razonar.")],
  [E("¿Qué palabras ayudan a escribir una pregunta interpretativa: «por qué» y «qué sugiere» o «cuándo» y «dónde»?", "«por qué» y «qué sugiere»", "Piden razonar y no solo buscar un dato."),
   E("¿Con qué se responden las preguntas literales: con una frase explícita del texto o con una opinión sin evidencia?", "Con una frase explícita del texto", "Buscan un dato que el texto dice directamente."),
   E("¿Qué necesita una pregunta interpretativa para no ser demasiado amplia: anclarse en un detalle del texto o ser más larga?", "Anclarse en un detalle del texto", "Así el texto puede responderla.")],
  (f"Lee: «{FAROL}» 1) Escribe una pregunta literal. 2) Escribe dos preguntas interpretativas ancladas en detalles. 3) Elige una y anota una evidencia que usarías para responderla.",
   "Literal: ¿Qué guía a los niños en la noche de neblina? Interpretativas: ¿Por qué Anselmo no deja de encender el farol? ¿Qué sugiere el texto sobre depender solo de lo nuevo? Evidencia: «las luces nuevas se apagaron por una falla».",
   ["una pregunta literal", "dos interpretativas ancladas", "evidencia pertinente"], ["tres preguntas y una cita"], ["preguntas demasiado amplias", "pregunta literal disfrazada"], "Comprueba que cada pregunta interpretativa tenga más de una respuesta razonable."),
  "Elige un cuento que conozcas y escribe dos preguntas interpretativas.",
  "Escribe una pregunta interpretativa sobre un poema y otra sobre un cuento, con una evidencia para cada una.")

NORA = ("Nora llegó a la meta cuando ya casi todos se habían ido. Sus piernas temblaban y el cronómetro marcaba mucho más que los demás. "
        "Pero al cruzar la línea escuchó aplausos: sus compañeros habían esperado en la pista. Nora sonrió con los ojos brillantes y no dijo nada.")

L(OA7, 2,
  MAT,
  "Aprenderé a relacionar un texto con mi experiencia y mis conocimientos usando evidencia del texto, sin estar obligado a contar mi vida personal.",
  ["Formulo preguntas interpretativas.", "Sé citar el texto."],
  ["Interpretar un texto implica relacionarlo con lo que sabemos. Esos saberes pueden venir de muchas fuentes: lo que hemos leído en otros textos, lo que hemos visto en películas o noticias, lo que aprendemos en clases, lo que nos han contado y, si queremos, de nuestra experiencia personal. La experiencia personal es una fuente posible, pero nunca obligatoria: nadie tiene que contar su vida para interpretar bien.",
   "La clave es usar esos saberes como apoyo, no como reemplazo del texto. Una buena conexión tiene tres pasos: citar una evidencia del texto («escuchó aplausos: sus compañeros habían esperado»), relacionarla con un saber («en las carreras largas muchas personas aplauden a quienes llegan al final») y concluir qué ilumina («el texto valora el esfuerzo más que el primer lugar»). Si el saber no se conecta con la evidencia, no aporta a la interpretación.",
   "También hay que cuidar la intimidad. Podemos usar ejemplos imaginados («una persona que llega última a una carrera podría sentirse…»), conocimientos generales o casos de otros textos. Así protegemos a las personas que nombramos y evitamos exponer asuntos familiares. Una conexión no debe distorsionar el texto: si mi experiencia dice una cosa y el texto muestra otra, prevalece lo que el texto muestra."],
  [("conexión", "relación entre el texto y algo que sabemos"), ("conocimiento previo", "lo que ya sabemos por lecturas, clases o experiencias"), ("intimidad", "lo privado de cada persona"), ("evidencia", "dato del texto que respalda una idea")],
  [("Elegir la evidencia", f"Texto: «{NORA}» ¿Qué evidencia sirve para sostener que se valora el esfuerzo: «sus compañeros habían esperado en la pista» o «el cronómetro marcaba mucho más»?",
    ["Busco algo que muestre reconocimiento.", "Los compañeros esperan y aplauden.", "Sirve «sus compañeros habían esperado en la pista»."],
    "«sus compañeros habían esperado en la pista»"),
   ("Conectar sin autobiografía", "¿Cómo puedes conectar el texto de Nora con un saber sin contar tu vida: «En las carreras largas se aplaude a quienes llegan al final» o «Mi familia...»?",
    ["Busco un conocimiento general.", "El primero es un saber compartido y no expone a nadie.", "Elijo «En las carreras largas se aplaude a quienes llegan al final»."],
    "«En las carreras largas se aplaude a quienes llegan al final»")],
  [("Contar una experiencia privada para participar.", "Se piensa que la conexión debe ser personal.", "Usa conocimientos generales, otros textos o ejemplos imaginados."),
   ("Usar un saber que contradice el texto.", "Se deja que la experiencia reemplace la lectura.", "Prioriza lo que el texto muestra.")],
  ([E("¿Se puede interpretar bien un texto sin contar tu experiencia personal?", "Sí", "Hay otras fuentes de conexión."),
    E(f"Texto: «{NORA}» ¿Qué hacen los compañeros cuando Nora llega: esperan y aplauden o se van?", "Esperan y aplauden", "Lo dice el texto."),
    E("Un conocimiento previo, ¿es lo que ya sabemos por lecturas, clases o experiencias o lo que inventamos?", "Lo que ya sabemos", "Se usa como apoyo.")],
   [E(f"Texto: «{NORA}» ¿Qué saber general se conecta con el texto: «en una maratón también se aplaude a quienes llegan últimos» o «los relojes miden el tiempo»?", "«en una maratón también se aplaude a quienes llegan últimos»", "Se relaciona con el aplauso a quien llega tarde."),
    E("Un compañero cuenta un problema de su familia para opinar. ¿Qué podría usar en su lugar: un ejemplo imaginado o el nombre de su vecino?", "Un ejemplo imaginado", "Protege la intimidad."),
    E(f"Texto: «{NORA}» ¿Qué muestra «sonrió con los ojos brillantes y no dijo nada»: emoción contenida o enojo?", "Emoción contenida", "Es una pista de sentimiento.")],
   [E(f"Texto: «{NORA}» Ordena los tres pasos de una buena conexión escribiendo los números: 1) concluir qué ilumina, 2) citar una evidencia, 3) relacionarla con un saber.", "2, 3, 1", "Primero evidencia, luego saber y al final conclusión."),
    E(f"Texto: «{NORA}» Conclusión: «El texto valora el esfuerzo más que el primer lugar». ¿Qué evidencia respalda mejor: «escuchó aplausos» o «llegó a la meta»?", "«escuchó aplausos»", "El aplauso muestra el valor otorgado al esfuerzo."),
    E("Un compañero relaciona el texto con otro cuento donde un perdedor es aplaudido. ¿Qué fuente de conocimiento usa ese compañero: otro texto leído o una experiencia privada?", "Otro texto leído", "Un cuento relacionado es una fuente para interpretar.")],
   [E(f"Texto: «{NORA}» Alguien dice: «Yo sé que en mi barrio nadie aplaude a quien llega tarde, así que el texto exagera». ¿Qué error comete: poner su experiencia por sobre lo que el texto muestra o citar mal el texto?", "Poner su experiencia por sobre lo que el texto muestra", "El texto muestra aplausos y debe analizarlo."),
    E("¿Qué evita exponer a otras personas al conectar un texto: los ejemplos imaginados o nombrar a conocidos?", "Los ejemplos imaginados", "No revelan datos privados.")],
   [E(f"Texto: «{NORA}» Escribe una conexión de tres partes. ¿Cuál es la mejor: «Dice que escuchó aplausos; en las carreras se aplaude a quienes terminan; por eso valora el esfuerzo» o «Me recuerda a mi vida»?", "«Dice que escuchó aplausos; en las carreras se aplaude a quienes terminan; por eso valora el esfuerzo»", "Incluye evidencia, saber y conclusión."),
    E(f"Texto: «{NORA}» Si el texto dijera que los compañeros se rieron, ¿se mantendría la misma conexión?", "No", "Cambiaría la evidencia y la interpretación.")]),
  [E("En clase leen el cuento de Nora. Una compañera dice que le recuerda una escena de una película donde un equipo espera al último corredor. ¿Esa conexión expone la intimidad de alguien: sí o no?", "No", "Usa una obra conocida y no revela datos privados.")],
  [E("¿Cuál de estas es una fuente de saberes para interpretar: una película vista o un secreto de un vecino?", "Una película vista", "Los secretos de otras personas no deben usarse."),
   E("La experiencia personal, ¿es una fuente obligatoria o una fuente posible?", "Una fuente posible", "Es opcional y nadie debe exponer su vida privada."),
   E("¿Qué prevalece si mi saber contradice el texto: el texto o mi saber?", "El texto", "La interpretación se apoya en él.")],
  (f"Lee: «{NORA}» 1) Cita una evidencia. 2) Escribe un saber (de otro texto, de clases o general) que se conecte. 3) Escribe una conclusión que una ambos, sin contar vivencias privadas.",
   "Evidencia: «escuchó aplausos: sus compañeros habían esperado». Saber: en muchas competencias se aplaude a quienes terminan. Conclusión: el texto valora la constancia más que el primer lugar.",
   ["cita una evidencia", "usa un saber no privado", "conclusión coherente"], ["tres frases"], ["contar la vida privada", "saber sin relación"], "Comprueba que el saber que usaste se pueda explicar a otra persona sin nombrar a nadie."),
  "Piensa en un cuento que conozcas y escribe una conexión con otro texto, sin hablar de tu familia.",
  "Escribe dos conexiones distintas para el cuento de Nora y decide cuál tiene más evidencia.")

DILEMA = ("Leo vio que su mejor amigo, Iván, copiaba las respuestas de un compañero durante la prueba. Si lo contaba, Iván podía recibir un cero y sentirse traicionado. "
          "Si se quedaba callado, los otros estudiantes, que habían estudiado, saldrían perjudicados. Leo guardó el lápiz y no dijo nada, pero el resto del día se sintió inquieto.")

L(OA7, 3,
  MAT,
  "Aprenderé a analizar un dilema presentado en un texto: reconocer los valores en conflicto, las alternativas y sus consecuencias.",
  ["Reconozco el conflicto de una narración.", "Formulo preguntas interpretativas."],
  ["Un dilema es una situación en que un personaje debe elegir entre dos o más caminos, y todos tienen costos. No hay una opción perfecta: cada alternativa protege un valor y sacrifica otro. En el texto de Leo, el dilema enfrenta la lealtad a un amigo con la honestidad y la justicia hacia los demás compañeros.",
   "Para analizar un dilema se siguen cuatro pasos. Primero, identificar la decisión que el personaje debe tomar. Segundo, nombrar los valores en tensión (lealtad, honestidad, justicia, solidaridad). Tercero, enumerar las alternativas posibles, incluyendo las intermedias: Leo podría callar, avisar al profesor o hablar primero con Iván. Cuarto, evaluar las consecuencias de cada alternativa para cada persona.",
   "Analizar no es decidir todavía quién tiene la razón, sino comprender la situación a fondo. Conviene preguntar quién sale beneficiado y quién perjudicado con cada alternativa, y qué información falta. Una buena alternativa suele combinar valores: hablar con Iván antes de avisar permite proteger la amistad y la justicia a la vez. Los dilemas muestran que las decisiones morales pueden ser difíciles."],
  [("dilema", "situación en que hay que elegir entre opciones que tienen costos"), ("valor", "principio que se considera importante, como la lealtad"), ("alternativa", "opción posible entre varias"), ("consecuencia", "resultado de una decisión")],
  [("Nombrar los valores", f"Texto: «{DILEMA}» ¿Qué valores están en tensión?",
    ["Veo qué protege callar: la amistad y lealtad con Iván.", "Veo qué protege contarlo: la justicia hacia los demás.", "Se oponen la lealtad y la honestidad o justicia."],
    "La lealtad frente a la honestidad o justicia"),
   ("Proponer una alternativa intermedia", f"Texto: «{DILEMA}» ¿Qué alternativa intermedia podría tomar Leo además de callar o avisar al profesor?",
    ["Pienso en una opción que combine valores.", "Podría hablar primero con Iván y pedirle que lo corrija.", "Esa opción protege la amistad y la justicia."],
    "Hablar primero con Iván")],
  [("Pensar que un dilema tiene una respuesta correcta evidente.", "Se ignora el costo de cada opción.", "Analiza qué protege y qué sacrifica cada alternativa."),
   ("Considerar solo dos alternativas.", "Se olvida el camino intermedio.", "Busca opciones que combinen valores.")],
  ([E(f"Texto: «{DILEMA}» ¿Qué vio Leo: que su amigo copiaba o que su amigo estudiaba?", "Que su amigo copiaba", "Lo dice la primera oración."),
    E("Un dilema, ¿es una situación con una opción perfecta o con opciones que tienen costos?", "Con opciones que tienen costos", "Ninguna alternativa es perfecta."),
    E(f"Texto: «{DILEMA}» ¿Qué decidió hacer Leo al final?", "No decir nada", "El texto dice que no dijo nada.")],
   [E(f"Texto: «{DILEMA}» ¿Qué riesgo corre Iván si Leo lo cuenta?", "Recibir un cero y sentirse traicionado", "El texto lo plantea."),
    E(f"Texto: «{DILEMA}» ¿Quiénes salen perjudicados si Leo calla?", "Los estudiantes que sí estudiaron", "Compiten en desventaja."),
    E(f"Texto: «{DILEMA}» ¿Qué muestra la frase «se sintió inquieto»: un conflicto interno tras su decisión o satisfacción por su silencio?", "Un conflicto interno tras su decisión", "Revela que no está tranquilo con su silencio.")],
   [E(f"Texto: «{DILEMA}» Une cada alternativa con un valor que protege principalmente. Alternativas: 1) callar, 2) avisar al profesor, 3) hablar primero con Iván. Valores: A) justicia, B) lealtad, C) lealtad y justicia a la vez. Escribe las tres letras en orden.", "B, A, C", "Cada alternativa protege un valor distinto."),
    E(f"Texto: «{DILEMA}» ¿Cuántas alternativas distintas se nombran en la clase para Leo: callar, avisar al profesor y hablar primero con Iván?", "3", "Son tres caminos posibles diferentes."),
    E(f"Texto: «{DILEMA}» ¿Qué información falta para evaluar mejor la decisión: qué tan grave sería la sanción de Iván o el color de su lápiz?", "Qué tan grave sería la sanción de Iván", "Ayudaría a pesar las consecuencias.")],
   [E(f"Texto: «{DILEMA}» Un lector dice que la opción correcta es evidente: avisar. ¿Qué costo ignora?", "Que Iván podría sentirse traicionado y recibir un cero", "Toda alternativa tiene un costo."),
    E(f"Texto: «{DILEMA}» ¿Qué alternativa intenta combinar lealtad y justicia: callar, avisar al profesor o hablar primero con Iván?", "Hablar primero con Iván", "Le da la oportunidad de corregir sin traicionarlo.")],
   [E(f"Texto: «{DILEMA}» Si Leo no hubiera visto nada, ¿habría dilema?", "No", "El dilema nace de que sabe lo que ocurrió."),
    E(f"Texto: «{DILEMA}» Si Iván fuera un desconocido en lugar de su mejor amigo, ¿qué valor pesaría menos en la decisión: la lealtad o la justicia?", "La lealtad", "El vínculo cambia la tensión entre valores.")]),
  [E("Una vecina encuentra una billetera con dinero y una tarjeta con el nombre del dueño. Si la devuelve, pierde la posibilidad de usar el dinero que necesita; si no, perjudica a alguien. ¿Qué valores están en tensión?", "La honestidad y la necesidad personal", "Son los que se oponen en la decisión.")],
  [E("¿Qué es una alternativa intermedia: una opción que combina valores o una opción que los ignora?", "Una opción que combina valores", "Busca proteger más de uno."),
   E("¿Cuál es el primer paso para analizar un dilema: identificar la decisión que debe tomarse o decidir quién tiene la razón?", "Identificar la decisión que debe tomarse", "Se parte de lo que hay que decidir."),
   E("Al analizar un dilema, ¿se comprende primero la situación antes de decidir quién tiene la razón?", "Sí", "Primero se comprende la situación.")],
  (f"Lee: «{DILEMA}» 1) Escribe la decisión que debe tomar Leo. 2) Nombra dos valores en tensión. 3) Evalúa dos alternativas con su consecuencia principal.",
   "Decisión: contar o no que su amigo copia. Valores: lealtad y justicia. Alternativas: callar (protege a Iván pero perjudica a otros); hablar con Iván (puede resolverlo, aunque Iván podría negarse).",
   ["identifica la decisión", "dos valores en tensión", "evalúa consecuencias"], ["tres respuestas"], ["una sola alternativa", "ignorar costos"], "Escribe junto a cada alternativa quién gana y quién pierde."),
  "Piensa en un dilema de un cuento que conozcas y anota los valores en tensión.",
  "Escribe un dilema de seis líneas con tres alternativas posibles.")

L(OA7, 4,
  MAT,
  "Aprenderé a construir una postura personal fundamentada frente a un dilema del texto, con razones, evidencia y una respuesta a una objeción.",
  ["Analizo un dilema y sus alternativas.", "Escribo una reflexión con evidencia."],
  ["Una postura es la posición que yo tomo frente a una pregunta o a un dilema: «Creo que Leo debería hablar primero con Iván». Una postura es fundamentada cuando tiene razones y evidencia. Las razones explican por qué pienso así. La evidencia es el dato del texto que las respalda. Sin ambas, la postura es solo una opinión.",
   "Una postura sólida tiene cuatro partes. Primera, la afirmación clara. Segunda, una o dos razones. Tercera, una evidencia del texto por razón. Cuarta, una objeción posible y una respuesta: «Podrían decir que hablar con Iván lo avisa y le da tiempo de ocultar la copia; sin embargo, el texto muestra que Leo se siente inquieto y quiere una solución justa». Considerar otra mirada demuestra seriedad.",
   "Las posturas pueden ser distintas y todas ser razonables si se apoyan en el texto. Se debe cuidar que la razón no contradiga la evidencia. También es importante expresarse con respeto: no se critica a quien piensa distinto, sino que se discute la idea. Al revisar una postura, se pregunta: ¿se entiende mi afirmación?, ¿cada razón tiene evidencia?, ¿respondí una objeción?"],
  [("postura", "posición personal frente a una pregunta o dilema"), ("razón", "motivo que explica por qué pienso así"), ("objeción", "argumento contrario a mi postura"), ("fundamentar", "apoyar una postura con razones y evidencia")],
  [("Identificar las partes", "Postura: «Leo debería hablar primero con Iván, porque el texto muestra que se siente inquieto y quiere ser justo». ¿Cuál es la razón?",
    ["Busco el porqué.", "La razón es que Leo se siente inquieto y quiere ser justo.", "La afirmación es lo que debería hacer."],
    "Porque Leo se siente inquieto y quiere ser justo"),
   ("Responder una objeción", "Objeción: «Si Leo habla con Iván, este podría negar todo». ¿Qué respuesta fortalece la postura?",
    ["Reconozco que la objeción tiene sentido.", "Respondo con una razón del texto.", "Aunque Iván lo niegue, Leo habrá actuado con honestidad y podrá decidir después si avisa."],
    "Leo habrá actuado con honestidad y podrá decidir después si avisa")],
  [("Dar una postura sin razones: «Debería avisar porque sí».", "Se confunde postura con opinión.", "Agrega una razón y una evidencia."),
   ("Ignorar las objeciones.", "Se piensa que solo importa la propia mirada.", "Reconoce y responde una mirada distinta.")],
  ([E(f"Texto: «{DILEMA}» Postura: «Leo debería hablar con Iván». ¿Es una afirmación, una razón o una evidencia?", "Una afirmación", "Es la posición."),
    E("Una postura fundamentada, ¿tiene razones y evidencia o solo la opinión de quien la dice?", "Razones y evidencia", "Por eso se puede discutir."),
    E("¿Cuántas partes tiene una postura sólida según la clase?", "4", "Afirmación, razón, evidencia y objeción con respuesta.")],
   [E(f"Texto: «{DILEMA}» ¿Qué dato del texto respalda la razón «Leo no está tranquilo con su silencio»?", "«el resto del día se sintió inquieto»", "Es la evidencia que muestra su inquietud."),
    E("Objeción: «Si habla con Iván, lo avisa y Iván se justificará». ¿Qué función cumple esa frase en el debate: objeción a la postura o apoyo a la postura?", "Objeción a la postura", "Plantea un argumento contrario."),
    E("¿Cuál es la afirmación en «Creo que Leo debería avisar al profesor, porque la justicia hacia los demás es importante»?", "«Leo debería avisar al profesor»", "Es la posición; lo que sigue es la razón.")],
   [E("Ordena las partes de una postura escribiendo los números: 1) objeción y respuesta, 2) razón, 3) afirmación, 4) evidencia.", "3, 2, 4, 1", "Se parte de la afirmación, luego razón, evidencia y objeción."),
    E(f"Texto: «{DILEMA}» Elige la postura mejor fundamentada: «Leo debió callar porque los amigos se protegen» o «Leo debió hablar con Iván, porque el texto muestra que callar lo dejó inquieto y perjudicó a los demás». ¿Cuál?", "La segunda", "Incluye razón y evidencia."),
    E("Un compañero responde a una postura con «tú no entiendes nada». ¿Es una objeción adecuada o un ataque a la persona?", "Un ataque a la persona", "Una objeción discute la idea.")],
   [E(f"Texto: «{DILEMA}» Una razón dice «Leo debería callar porque los amigos siempre se protegen». ¿Qué evidencia del texto contradice esa razón?", "Que los otros estudiantes saldrían perjudicados", "El texto muestra el costo para terceros."),
    E("Dos personas tienen posturas distintas, pero ambas apoyadas en el texto. ¿Es posible que ambas sean razonables?", "Sí", "Un dilema admite lecturas distintas.")],
   [E(f"Texto: «{DILEMA}» Redacta: afirmación «Leo debió hablar con Iván»; razón «protege la justicia sin traicionar»; evidencia «los otros estudiantes saldrían perjudicados». ¿Qué falta para completar la postura de 4 partes?", "Una objeción con su respuesta", "Faltan la objeción y su respuesta."),
    E("Una persona cambia su postura al conocer un dato nuevo del texto. ¿Es un signo de debilidad o de buen razonamiento?", "De buen razonamiento", "Revisar con evidencia es correcto.")]),
  [E("En un debate sobre si debe permitirse el celular en recreos, Ana dice «Sí, porque ayuda a hablar con la familia». Beto responde «No, porque nos distrae de jugar». ¿Cuál de las dos posturas tiene razón explícita?", "Las dos", "Ambas incluyen un «porque».")],
  [E("¿Qué explica por qué pienso así: la afirmación o la razón?", "La razón", "Justifica la afirmación."),
   E("¿Qué es una objeción: un argumento contrario a mi postura o una razón que la apoya?", "Un argumento contrario a mi postura", "Se responde para fortalecer la postura."),
   E("¿Se discute la idea o a la persona?", "La idea", "Las ideas se discuten y las personas se respetan.")],
  (f"Lee: «{DILEMA}» Escribe una postura fundamentada de cuatro partes: afirmación, una razón con evidencia del texto y una objeción con su respuesta. Máximo seis líneas.",
   "Creo que Leo debió hablar primero con Iván. Esto protege la justicia sin traicionar la amistad, porque el texto dice que callar lo dejó «inquieto». Podrían decir que Iván lo negaría; sin embargo, Leo habría actuado con honestidad y podría luego avisar al profesor.",
   ["afirmación clara", "razón con evidencia", "objeción respondida"], ["texto de seis líneas"], ["postura sin razones", "ataque a la persona"], "Subraya las cuatro partes con colores distintos."),
  "Cuéntale a alguien de tu casa tu postura sobre el dilema de Leo y escucha una objeción.",
  "Escribe dos posturas contrarias sobre el dilema de Leo, ambas con evidencia.")

ALDEA = ("En la aldea de Valle Alto, cuando comenzaba la cosecha, todos dejaban sus tareas para trabajar los campos de cada familia, uno por uno. Rodrigo, un joven que prefería pintar, "
         "fue visto en la ladera con su caballete mientras sus vecinos cosechaban. Nadie le gritó, pero esa noche ninguna puerta se abrió para ofrecerle sopa. "
         "Al día siguiente, Rodrigo dejó el pincel y fue a cosechar.")

L(OA7, 5,
  MAT,
  "Aprenderé a vincular una obra con la visión de mundo de la comunidad o época que muestra o en que fue creada.",
  ["Interpreto con evidencia.", "Reconozco contexto y valores en un texto."],
  ["La visión de mundo es el conjunto de ideas, creencias y valores sobre cómo es el mundo y cómo debe vivirse en él. Cada comunidad y cada época tienen la suya. Una obra literaria suele reflejarla, aunque a veces la cuestione. Por ejemplo, en una aldea donde la cosecha se hace entre todos, se espera que cada persona contribuya al trabajo común, y quien se aparta recibe señales de reproche aunque nadie grite.",
   "Para vincular obra y visión de mundo se hacen tres preguntas: ¿qué se espera de las personas en este mundo?, ¿qué conductas se premian o se castigan, y cómo? y ¿qué valor aparece como más importante? En el texto de Valle Alto, el valor central es el trabajo colectivo. La reacción silenciosa de los vecinos muestra una sanción social sin violencia. Y la decisión de Rodrigo de dejar el pincel revela el peso de esa visión de mundo sobre sus elecciones.",
   "Es importante no juzgar una visión de mundo solo desde la nuestra. Primero la comprendemos: qué la sostiene, qué problemas resolvía y qué costos tenía. Luego, si queremos, la valoramos con razones. Y también debemos evitar generalizar: el texto muestra una aldea, no todas. Una interpretación situada reconoce que lo que consideramos normal hoy puede ser distinto de lo que se consideraba normal en otro tiempo o lugar."],
  [("visión de mundo", "conjunto de ideas y valores sobre cómo es el mundo y cómo debe vivirse"), ("sanción social", "reacción de la comunidad ante una conducta, como el rechazo"), ("trabajo colectivo", "trabajo hecho entre todos"), ("anacronismo", "juzgar o explicar el pasado con ideas de hoy sin considerar su época")],
  [("Qué se espera de las personas", f"Texto: «{ALDEA}» ¿Qué se espera de cada persona en Valle Alto durante la cosecha?",
    ["Leo cómo se comportan los vecinos.", "Todos dejan sus tareas para trabajar los campos de cada familia.", "Se espera que cada persona contribuya al trabajo colectivo."],
    "Que contribuya al trabajo colectivo"),
   ("Reconocer una sanción", f"Texto: «{ALDEA}» ¿Cómo muestra la aldea su rechazo a Rodrigo?",
    ["Busco qué hace la comunidad.", "Nadie le grita, pero ninguna puerta se abre para ofrecerle sopa.", "Con una sanción social silenciosa."],
    "Con una sanción social silenciosa: nadie le ofrece sopa")],
  [("Juzgar a la aldea solo con las ideas de hoy.", "Se olvida el contexto.", "Primero comprende qué sostiene esa visión de mundo."),
   ("Generalizar a todas las comunidades.", "Se toma un caso como regla.", "Habla de lo que el texto muestra de esa aldea.")],
  ([E(f"Texto: «{ALDEA}» ¿Qué prefería hacer Rodrigo: pintar o cosechar?", "Pintar", "El texto lo dice."),
    E("La visión de mundo, ¿es un conjunto de ideas y valores sobre cómo vivir o una lista de objetos?", "Un conjunto de ideas y valores sobre cómo vivir", "Define lo que una comunidad considera importante."),
    E(f"Texto: «{ALDEA}» ¿Qué dejó Rodrigo al día siguiente?", "El pincel", "Dejó el pincel y fue a cosechar.")],
   [E(f"Texto: «{ALDEA}» ¿Qué valor central muestra la aldea: el trabajo colectivo o la competencia entre vecinos?", "El trabajo colectivo", "Todos cosechan los campos de cada familia."),
    E(f"Texto: «{ALDEA}» ¿Hubo gritos contra Rodrigo: sí o no?", "No", "El texto dice «Nadie le gritó»."),
    E(f"Texto: «{ALDEA}» ¿Qué muestra que Rodrigo asumió la presión de la comunidad?", "Que dejó el pincel y fue a cosechar", "Cambió su conducta tras el rechazo.")],
   [E(f"Texto: «{ALDEA}» Une cada evidencia con lo que muestra. Evidencias: 1) «todos dejaban sus tareas», 2) «ninguna puerta se abrió», 3) «dejó el pincel». Muestra: A) rechazo de la comunidad, B) norma de ayudarse, C) Rodrigo se adapta. Escribe las tres letras en orden.", "B, A, C", "1 muestra la norma; 2, el rechazo; 3, su adaptación."),
    E(f"Texto: «{ALDEA}» ¿Qué sanción social aplican los vecinos a Rodrigo?", "Nadie le ofrece sopa esa noche", "Es un rechazo sin violencia."),
    E(f"Texto: «{ALDEA}» ¿Qué conducta se espera y valora en esa aldea?", "Contribuir al trabajo común", "Es lo que hacen todos en la cosecha.")],
   [E(f"Texto: «{ALDEA}» Un lector afirma: «La aldea es injusta con los artistas». ¿Es un juicio sin considerar su visión de mundo?", "Sí, hay que comprender primero qué la sostiene", "Se juzga desde afuera sin analizar la comunidad."),
    E("Un lector escribe: «Rodrigo debió publicar sus pinturas en una red social». ¿Qué error (anacronismo) comete?", "Usa un medio que no existía en ese mundo", "Proyecta el presente sobre el texto.")],
   [E(f"Texto: «{ALDEA}» Una interpretación situada dice: «El texto muestra una comunidad donde el bien común pesa más que la preferencia individual». ¿Qué evidencia es la más directa?", "«todos dejaban sus tareas para trabajar los campos de cada familia»", "Muestra la prioridad de lo colectivo."),
    E(f"Texto: «{ALDEA}» Si en otra comunidad se valorara el arte por sobre la cosecha, ¿cambiaría el final del cuento?", "Sí", "Cambiaría lo que se espera de Rodrigo.")]),
  [E("Lees un cuento ambientado en un tiempo sin teléfonos. En él, quien llega de visita sin avisar es recibido con comida y sin reproches. Un compañero dice que es una mala educación. ¿Qué valor de esa comunidad explica la costumbre?", "La acogida al visitante", "En ese mundo no se podía avisar y recibir bien a quien llegaba era importante; juzgarlo desde hoy sería un anacronismo.")],
  [E("¿Qué es una sanción social?", "Una reacción de la comunidad ante una conducta", "Puede ser rechazo o silencio."),
   E("Ante una visión de mundo distinta, ¿conviene comprender primero qué la sostiene antes de juzgarla?", "Sí", "Primero se comprende."),
   E("¿Qué pregunta ayuda a vincular obra y visión de mundo: «¿qué se espera de las personas en este mundo?» o «¿cuántas páginas tiene?»", "«¿qué se espera de las personas en este mundo?»", "Revela las normas implícitas.")],
  (f"Lee: «{ALDEA}» 1) Escribe qué visión de mundo muestra la aldea. 2) Cita dos evidencias. 3) Escribe una pregunta para comprender mejor ese mundo antes de juzgarlo.",
   "La aldea valora el trabajo colectivo por encima de la preferencia individual. Evidencias: «todos dejaban sus tareas para trabajar los campos» y «ninguna puerta se abrió para ofrecerle sopa». Pregunta: ¿qué pasaba si una familia no podía cosechar por estar enferma?",
   ["describe la visión de mundo", "dos evidencias", "pregunta que no juzga"], ["tres respuestas"], ["anacronismo", "generalizar"], "Comprueba que tu pregunta busca comprender, no criticar."),
  "Pregunta a una persona mayor qué se esperaba de las personas en su comunidad cuando era joven.",
  "Escribe una escena de seis líneas con una visión de mundo diferente a la de Valle Alto.")

TELEGRAMA = ("Cuando llegó el telegrama, Teresa tardó tres días en responder. Su hermano esperó en la estación cada tarde, convencido de que ella no quería verlo. "
             "Al cuarto día la vio bajar del tren con la maleta mojada y los ojos cansados: había viajado desde otra provincia en un tren lento, con dos transbordos.")

L(OA7, 6,
  MAT,
  "Aprenderé a revisar una interpretación inicial a la luz del contexto: mantenerla, ajustarla o cambiarla con nuevas evidencias.",
  ["Vinculo una obra con su visión de mundo.", "Formulo posturas fundamentadas."],
  ["Una primera interpretación es una hipótesis: una idea provisional que se pone a prueba. Revisarla significa volver al texto y al contexto y preguntar si sigue siendo la mejor explicación. A veces el contexto cambia el sentido de un hecho: lo que parece indiferencia puede ser una limitación de la época; lo que parece exageración puede ser una costumbre.",
   "Para revisar se siguen cuatro pasos. Primero, escribir la interpretación inicial con su evidencia. Segundo, buscar datos nuevos del texto o del contexto. Tercero, decidir si la interpretación se mantiene, se ajusta o se cambia. Cuarto, explicar qué dato motivó el cambio. En el texto de Teresa, la primera lectura puede ser «Teresa es indiferente». Pero el dato de que el viaje era largo y lento obliga a cambiarla: su demora tiene una causa práctica.",
   "Revisar no es admitir un error, sino mejorar la comprensión. Un lector competente cambia de idea cuando aparecen buenas razones y defiende su idea cuando sigue teniendo respaldo. También es importante usar contexto seguro. Si no estamos seguros de un dato histórico, lo consultamos antes de usarlo, para no inventar explicaciones que el texto no sostiene."],
  [("hipótesis", "idea provisional que se pone a prueba"), ("ajustar", "modificar una interpretación sin abandonarla del todo"), ("contexto", "mundo y circunstancias en que ocurre un texto"), ("revisar", "volver sobre una idea para comprobar si sigue siendo la mejor")],
  [("Primera lectura", f"Texto: «{TELEGRAMA}» Primera interpretación: «Teresa es indiferente porque tardó tres días». ¿Qué dato del texto la pone en duda?",
    ["Releo el final del texto.", "Teresa había viajado desde otra provincia en un tren lento con dos transbordos.", "Ese dato explica su demora por una causa práctica."],
    "Que viajó desde otra provincia en un tren lento con dos transbordos"),
   ("Decidir cómo revisar", f"Texto: «{TELEGRAMA}» Después de conocer el viaje, ¿cómo conviene revisar la primera interpretación: mantenerla, ajustarla o cambiarla?",
    ["Veo si el nuevo dato la contradice.", "La contradice casi del todo: no es indiferencia.", "Conviene cambiarla: la demora tiene una causa práctica."],
    "Cambiarla")],
  [("Defender la primera interpretación aunque aparezcan datos que la contradicen.", "Se confunde constancia con terquedad.", "Compara la hipótesis con los datos nuevos."),
   ("Cambiar de interpretación sin explicar qué dato lo motivó.", "Se pierde el respaldo.", "Anota el dato que motivó el cambio.")],
  ([E(f"Texto: «{TELEGRAMA}» ¿Cuántos días tardó Teresa en responder?", "Tres", "El texto lo dice."),
    E("Una hipótesis, ¿es una idea provisional que se pone a prueba o una verdad definitiva?", "Una idea provisional que se pone a prueba", "Se revisa con nuevos datos."),
    E(f"Texto: «{TELEGRAMA}» ¿Qué hizo su hermano cada tarde?", "Esperar en la estación", "El texto lo dice.")],
   [E(f"Texto: «{TELEGRAMA}» ¿Qué dato sobre el viaje muestra una causa práctica de la demora?", "«tren lento, con dos transbordos»", "Explica que no fue indiferencia."),
    E(f"Texto: «{TELEGRAMA}» ¿Qué muestran «la maleta mojada y los ojos cansados»: el esfuerzo del viaje o indiferencia?", "El esfuerzo del viaje", "Son pistas de un viaje difícil."),
    E("Revisar una interpretación, ¿es admitir un error o mejorar la comprensión?", "Mejorar la comprensión", "Se actualiza con datos nuevos.")],
   [E(f"Texto: «{TELEGRAMA}» Ordena los pasos para revisar escribiendo los números: 1) decidir mantener, ajustar o cambiar, 2) buscar datos nuevos, 3) escribir la interpretación inicial con su evidencia.", "3, 2, 1", "Primero la hipótesis, luego los datos nuevos y al final la decisión."),
    E(f"Texto: «{TELEGRAMA}» Interpretación inicial: «El hermano esperó porque era impaciente». Dato nuevo: «cada tarde, convencido de que ella no quería verlo». ¿Cómo conviene ajustar la interpretación: su espera se debía a la duda sobre ella o a su impaciencia?", "A la duda sobre ella", "Su espera constante revela inquietud más que impaciencia."),
    E("Una compañera dice «los telegramas llegaban siempre en minutos». ¿Debe usarse ese dato sin comprobarlo?", "No", "Si no está segura, debe consultarlo.")],
   [E(f"Texto: «{TELEGRAMA}» ¿Qué dato motivó el cambio de interpretación sobre Teresa?", "El viaje largo y lento", "Contradice la idea de indiferencia."),
    E(f"Texto: «{TELEGRAMA}» Una lectora sostiene que Teresa sí era indiferente. ¿Qué evidencia debería explicar para sostener esa lectura?", "Que llegó con la maleta mojada y los ojos cansados", "Esos detalles apuntan a un viaje fatigoso y a interés por llegar.")],
   [E(f"Texto: «{TELEGRAMA}» Reescribe: «Teresa no tardó por indiferencia, porque el viaje era largo y lento». ¿Qué dato respalda esa nueva interpretación?", "El viaje largo y lento con dos transbordos", "Es el dato que explica la demora."),
    E(f"Texto: «{TELEGRAMA}» ¿Qué contexto seguro ayuda a comprender la demora: que los viajes de larga distancia eran más lentos en ese mundo o que Teresa odiaba los trenes?", "Que los viajes de larga distancia eran más lentos en ese mundo", "Explica la demora sin inventar datos.")]),
  [E("Lees que un personaje no respondió una invitación en una semana. Piensas que fue descortés. Luego descubres que el cuento ocurre en una época en que las cartas tardaban semanas en llegar. ¿Qué haces con tu interpretación: la mantienes o la cambias?", "La cambio, porque el dato nuevo explica la demora", "El contexto de la época cambia el sentido del hecho: ya no es descortesía.")],
  [E("¿Qué se hace con una hipótesis cuando aparecen datos nuevos: se revisa o se mantiene sin mirarlos?", "Se revisa", "Se compara con los datos nuevos."),
   E("¿Qué debe anotarse al cambiar una interpretación: el dato que motivó el cambio o el nombre del lector?", "El dato que motivó el cambio", "Mantiene el respaldo de la nueva idea."),
   E("Con un dato histórico dudoso, ¿conviene consultarlo antes de usarlo?", "Sí", "Se consulta antes.")],
  (f"Lee: «{TELEGRAMA}» 1) Escribe una primera interpretación. 2) Anota un dato que la ponga a prueba. 3) Decide si la mantienes, la ajustas o la cambias y explica por qué en dos líneas.",
   "Primera interpretación: Teresa es indiferente. Dato: viajó desde otra provincia en un tren lento con dos transbordos. La cambio: su demora no se debe a falta de cariño, sino a la dificultad del viaje.",
   ["interpretación inicial", "dato nuevo pertinente", "decisión explicada"], ["tres respuestas"], ["defender sin datos", "cambiar sin explicar"], "Revisa que el dato que usaste esté en el texto."),
  "Recuerda una interpretación que cambiaste sobre un cuento y explica qué la modificó.",
  "Escribe una escena corta donde un contexto cambie el sentido de una acción.")
